/**
 * Voice mode helpers (pure, unit-tested). BETA.
 *
 * Voice mode = ask by voice (the browser's SpeechRecognition, see ./voice.ts) + hear the answer (the browser's speechSynthesis).
 * Both are built into the browser and free. Keplar never receives, records or stores audio: recognition returns text to the page,
 * and playback is generated by the browser from text already on the page. Some browsers send the audio to their vendor for
 * recognition, and some voices are online voices; that is the browser vendor's service, which the privacy page says.
 */

export type VoiceSupport = { recognition: boolean; synthesis: boolean };

type Win = { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown; speechSynthesis?: unknown; SpeechSynthesisUtterance?: unknown } | undefined;

export function voiceSupport(win: Win): VoiceSupport {
  return {
    recognition: Boolean(win?.SpeechRecognition ?? win?.webkitSpeechRecognition),
    synthesis: Boolean(win?.speechSynthesis && win?.SpeechSynthesisUtterance),
  };
}

/** The honest sentence shown when part of voice mode isn't available. Empty string = everything works. */
export function unsupportedMessage(s: VoiceSupport): string {
  if (s.recognition && s.synthesis) return "";
  if (!s.recognition && !s.synthesis) return "Voice mode isn't available in this browser: it has no built-in speech recognition and no read-aloud voices. Chrome, Edge and Safari support it (Firefox does not yet). You can keep typing.";
  if (!s.recognition) return "This browser can read answers aloud but can't turn your speech into text (Firefox, for example, doesn't support that yet). Use Chrome, Edge or Safari to ask by voice, or keep typing.";
  return "You can ask by voice here, but this browser has no read-aloud voices, so answers stay on screen. Chrome, Edge and Safari can read them aloud.";
}

/** Longest text read aloud for one answer. Longer answers are read up to a sentence boundary and the card says so. */
export const SPEAK_MAX_CHARS = 5000;

/** Turns an answer's markdown into text that sounds right when read: no symbols spoken, code and tables not read out. */
export function speakableText(markdown: string, max = SPEAK_MAX_CHARS): { text: string; truncated: boolean } {
  let t = markdown.replace(/\r\n?/g, "\n");
  t = t.replace(/```[\s\S]*?(```|$)/g, "\nCode example omitted.\n");
  t = t.replace(/<[^>]+>/g, " ");
  t = t.replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1");
  t = t.replace(/\[([^\]]+)\]\([^)]*\)/g, "$1");
  t = t.replace(/\[\^?\d+\]/g, "");
  t = t.replace(/\bhttps?:\/\/\S+/g, "a link");
  const lines = t.split("\n").flatMap((raw) => {
    let l = raw.trim();
    if (!l) return [""];
    if (/^\|?[\s:|-]+\|?$/.test(l) && l.includes("-")) return []; // table separator row
    if (/^\|.*\|$/.test(l)) l = l.slice(1, -1).split("|").map((c) => c.trim()).filter(Boolean).join(", ");
    l = l.replace(/^#{1,6}\s+/, "").replace(/^>\s?/, "").replace(/^([-*+]|\d+[.)])\s+/, "");
    l = l.replace(/(\*\*|__)(.*?)\1/g, "$2").replace(/(\*|_)(.*?)\1/g, "$2").replace(/`([^`]*)`/g, "$1").replace(/~~(.*?)~~/g, "$1");
    l = l.replace(/[*_`#>|]+/g, " ").replace(/\s+/g, " ").trim();
    if (!l) return [];
    return [/[.!?…:;]$/.test(l) ? l : `${l}.`];
  });
  let text = lines.join("\n").replace(/\n{2,}/g, "\n\n").trim();
  if (text.length <= max) return { text, truncated: false };
  const cut = text.slice(0, max);
  const at = Math.max(cut.lastIndexOf(". "), cut.lastIndexOf(".\n"), cut.lastIndexOf("? "), cut.lastIndexOf("! "));
  text = (at > max * 0.5 ? cut.slice(0, at + 1) : cut).trim();
  return { text, truncated: true };
}

/** Splits text into short utterances. Some browsers cut off long utterances, and short ones make stopping instant and clean. */
export function chunkForSpeech(text: string, max = 220): string[] {
  const out: string[] = [];
  for (const para of text.split(/\n+/)) {
    const sentences = para.split(/(?<=[.!?…])\s+/).map((s) => s.trim()).filter(Boolean);
    let cur = "";
    const push = () => { if (cur) out.push(cur); cur = ""; };
    for (const s of sentences) {
      if (s.length > max) {
        push();
        let rest = s;
        while (rest.length > max) {
          const cut = rest.slice(0, max);
          const at = Math.max(cut.lastIndexOf(", "), cut.lastIndexOf("; "), cut.lastIndexOf(" "));
          const n = at > max * 0.4 ? at + 1 : max;
          out.push(rest.slice(0, n).trim());
          rest = rest.slice(n).trim();
        }
        cur = rest;
      } else if (cur && cur.length + 1 + s.length > max) {
        push();
        cur = s;
      } else {
        cur = cur ? `${cur} ${s}` : s;
      }
    }
    push();
  }
  return out;
}

export type VoiceInfo = { lang: string; localService: boolean; default: boolean; name: string };

/** Picks a voice for `lang`: an on-device voice in that language first (nothing leaves the device), then any in that language, then the browser default. -1 = let the browser choose. */
export function pickVoice(voices: VoiceInfo[], lang: string): number {
  const L = lang.toLowerCase();
  const primary = L.split("-")[0];
  const same = (v: VoiceInfo) => v.lang.toLowerCase().replace("_", "-") === L;
  const sameLang = (v: VoiceInfo) => v.lang.toLowerCase().replace("_", "-").split("-")[0] === primary;
  const tiers: ((v: VoiceInfo) => boolean)[] = [(v) => same(v) && v.localService, (v) => sameLang(v) && v.localService, same, sameLang];
  for (const t of tiers) {
    const matches = voices.map((v, i) => ({ v, i })).filter(({ v }) => t(v));
    if (matches.length) return (matches.find(({ v }) => v.default) ?? matches[0]).i;
  }
  return -1;
}

/** Whether a push of the talk button was a quick tap (latch: keep listening until tapped again) or a hold (push-to-talk: release to send). */
export const TAP_MS = 350;
export const isTap = (heldMs: number) => heldMs < TAP_MS;
